Method.Implementation:

 Set oref=..%OpenId(oid,,.sc) If $$$ISERR(sc) Quit sc

 for ind = 1:1:oref.MyProp.Count()
 {

	set obj = oref.MyProp.GetAt(ind)

	If obj'=""  
	{
		Set sc1= ##class(IHC.ITF.ITFCOMMON.DataStructure.StoredProcParams).%Delete(obj.%Id())
		WRITE !, "DELETE " _ obj _ ", stat: " _ sc1
		If $$$ISERR(sc1) Set sc=$$$ADDSC(sc,sc1)
	}

 }
 &sql(Delete From IHC_ITF_ITFCOMMON_DataStructure.StoredProcParamsCollection Where Id=:oid )

 Quit $$$OK
